float random(vec2 st)
{
    return fract(sin(dot(st.xy, vec2(12.9898, 73.233))) * 434323.34353);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (fragCoord) / iResolution.xy;
    st*=20.0;

    vec2 fpos = fract(st);
    vec2 ipos = floor(st);



    vec3 color = vec3(random(iMouse.xy+ipos*2.0*random(ipos)), random(iMouse.xy+ipos*random(ipos)), random(iMouse.xy+ipos)*random(ipos));

    fragColor = vec4(color, 1.0);
}
